import {section,table,cite,topic,mountTopic,rangePlayback} from './topic-tools.js';
import {texEq as eq,inlineMath} from './math.js';
import {cells,traceLab,mountTrace} from './array-patterns-tools.js';
import {mergeTrace,schedulingTrace,overlapTrace,reachableTrace} from './search-choice-model.js';
export const greedyMeta={slug:'algorithms/greedy',title:'Greedy and Interval Algorithms',description:'Prove when one frontier dominates alternatives; connect reachability, prefix resets, interval union, scheduling, room counts and endpoint semantics.',date:'2026-04-08',updated:'2026-10-07',topicPath:['algorithms'],tags:['greedy','exchange argument','intervals','sweep line','meeting rooms','Kadane','frontier','scheduling'],learningGoals:['Separate a heuristic from a proven greedy rule.','Match an interval sort key to the objective.','Handle tied endpoints consistently in scheduling and sweeps.'],prototype:true,visibility:'public',kind:'dense-topic',related:['algorithms/dp','algorithms/backtracking','algorithms/windows']};
export const greedyAliases=[];
export const greedySections=[['commit','When can a choice become permanent?'],['proofs','Exchange, dominance and staying ahead'],['frontier','Keep the reachable frontier'],['frontier-lab','A gap stops reachability'],['reset','Discard a harmful prefix'],['counts','Construction follows forced choices'],['endpoints','Endpoints are part of the problem'],['merge','Sort starts to merge coverage'],['merge-lab','Only the last merged segment can overlap'],['insert','Insertion has three phases'],['scheduling','Sort finishes to keep the most intervals'],['schedule-lab','Earliest start can block three later jobs'],['rooms','Room count is maximum simultaneous demand'],['sweep-lab','Tied events change the active count'],['queries','Heap priorities depend on the query'],['choose','Choose an objective before choosing an order'],['sources','Sources and related mechanisms']];
const schedulingJobs=[[0,9],[1,3],[3,5],[5,7]],schedules=schedulingTrace(schedulingJobs),meetingJobs=[[1,3],[3,5],[2,4]],events=overlapTrace(meetingJobs),mergeFrames=mergeTrace([[1,3],[2,4],[4,6],[8,9]]),jumps=[2,0,0,1],frontierFrames=reachableTrace(jumps),name=i=>String.fromCharCode(65+i);
function timeline(jobs,current=null,selected=[],halfOpen=true){const lo=Math.min(0,...jobs.map(j=>j.start)),hi=Math.max(1,...jobs.map(j=>j.end)),width=hi-lo;return `<div class="interval-timeline" aria-label="Interval positions on a common time axis"><p>Shared time axis: ${lo} → ${hi}. Each row is one interval, not an assigned room.</p>${jobs.map(j=>`<div class="interval-row ${current===j.id?'interval-current':''}"><span>${name(j.id)} [${j.start},${j.end}${halfOpen?')':']'}</span><div class="interval-track"><i class="${selected.includes(j.id)?'interval-kept':''}" style="left:${100*(j.start-lo)/width}%;width:${100*(j.end-j.start)/width}%"></i></div></div>`).join('')}</div>`;}
function scheduleBody(f){return `${timeline(f.jobs,f.job?.id,f.kept.map(j=>j.id))}<p>${f.job?name(f.job.id)+': ':''}${f.message}</p><p>Kept: ${f.kept.length?f.kept.map(j=>name(j.id)).join(', '):'none'}. Count ${f.kept.length}. Finish frontier: ${f.end===-Infinity?'none':f.end}.</p><p>Blue-filled intervals are kept; an outlined row is being inspected. All bars use the same time scale. Compatibility permits start=previous end.</p>`;}
function sweepBody(f,closed=false){return `${timeline(f.jobs,f.event?.id,f.active,!closed)}<p>${f.message}</p><p>Endpoint policy: ${closed?'closed [start,end], starts before ends at a tie':'half-open [start,end), ends before starts at a tie'}.</p><p>Active: ${f.active.length?f.active.map(name).join(', '):'none'}; count ${f.count}. Maximum so far: ${f.maximum}.</p><p>A closed interval remains active at its ending coordinate. Half-open meetings release that coordinate before the next start.</p>`;}
function mergeBody(f){return `${timeline(f.jobs,f.job?.id,[],false)}<p>${f.job?name(f.job.id)+': ':''}${f.message}</p><p>Processed union: ${f.merged.length?f.merged.map(j=>`[${j.start},${j.end}]`).join(' · '):'empty'}.</p><p>The current last end can grow. Compare the next start with that updated end, not the first interval's old endpoint.</p>`;}
function frontierBody(f){return `${cells(jumps,f.index===null?[]:[f.index],jumps.map((_,i)=>i).filter(i=>i<=f.farthest))}<p>${f.message}</p><p>Farthest reachable index: ${f.farthest}. ${f.reachable?'No gap found in the processed prefix.':'Index '+f.index+' is unreachable; later jumps cannot be used.'}</p><p>Cell values are maximum jump lengths, not destinations. Blue fill marks reachable positions under the established frontier.</p>`;}
function variantLab(id,title,intro,selectLabel,options,frames,body){return traceLab(id,title,intro,frames,frames.length-1,body).replace('<label>Step',`<label>${selectLabel}<select aria-label="${selectLabel}">${options.map(([v,label])=>`<option value="${v}">${label}</option>`).join('')}</select></label><label>Step`);}
const scheduleLab=variantLab('schedule-lab','Earliest start can block three later jobs','Fixed half-open jobs A=[0,9), B=[1,3), C=[3,5), D=[5,7). Choose the sorting rule; all other conditions stay fixed.','Scheduling sort rule',[['end','Earliest finish (proven for maximum count)'],['start','Earliest start (counterexample)']],schedules,scheduleBody);
const sweepLab=variantLab('sweep-lab','Tied events change the active count','Fixed intervals A=(1,3), B=(3,5), C=(2,4). The control changes endpoint inclusion, not the numeric coordinates. Half-open demand peaks at 2; closed overlap peaks at 3.','Endpoint inclusion',[['half','Half-open [start,end)'],['closed','Closed [start,end]']],events,f=>sweepBody(f,false));
export function greedyReader(link){return topic(greedyMeta,greedySections,'Discard alternatives only when the proof says their future cannot be better.',`
<p>A greedy algorithm commits to a choice without later undoing it. The useful question is not “which choice looks best now?” It is “why can every discarded alternative be replaced or dominated without losing a better completion?”</p><p>Intervals make that distinction concrete. Merging all covered ranges, selecting the most compatible jobs and finding enough rooms are three different objectives. Each uses an order, but not the same invariant.</p>
${section('commit','When can a choice become permanent?',`<p>Suppose two partial states offer different futures. A locally smaller cost does not justify discarding the other if that state retains a needed option. <a href="${link('algorithms/dp#state')}">Dynamic Programming →</a> keeps sufficient alternatives when no single state dominates.</p><p>A two-stage cost example makes the failure explicit. One first choice costs 7 and then offers costs 9 or 10. Another costs 8 and then offers −5. Taking the locally cheaper edge at each step gives 7+9=16, while 8−5=3 is better. Later costs depend on the chosen branch, so the first edge alone cannot rank complete routes.</p>${table('Exact costs in the two-stage counterexample',['First choice','Second choice','Complete cost'],[['7','10','17'],['7','9','16: locally greedy route'],['8','−5','3: globally cheaper route']])}<p>For denominations 1,3,4 and amount 6, repeatedly taking the largest fitting coin gives 4+1+1. Two coins 3+3 are better. Sorting by size does not prove optimal coin count. This is an exact counterexample, not a statement that greedy never works for any denomination system.</p><p>When only feasibility or one optimum is required, a proof may allow a compact frontier. When all arrangements are requested, even an optimal local choice can remove other requested outputs. <a href="${link('algorithms/backtracking')}">Backtracking →</a> keeps those branches. A hypothetical search with ${inlineMath("2\\times10^{64}")} complete outcomes can motivate a shortcut, but this number is not a measured benchmark. Large search spaces can motivate greedy heuristics, but size does not prove optimality. A nearest-choice traveling-salesperson heuristic is not an exact solver for arbitrary instances.</p>`)}
${section('proofs','Exchange, dominance and staying ahead',`${table('What makes a commitment safe?',['Argument','Required comparison','Common failure'],[['Exchange','Transform an optimum to use the greedy choice without worsening it','Exchange changes a constraint or objective'],['Dominance','Every future continuation of a discarded state is matched by the retained state','States retain different future options'],['Stay ahead','At each decision, greedy has a frontier no worse than an alternative','A useful frontier is not shown to imply final quality']])}<p>Name the objective and input assumptions first. Then state the invariant, prove one step preserves it and connect the final state to the requested answer. A sort key is part of the algorithm, not a proof by itself.</p><p>“Highest gain,” “closest resource” and “highest frequency” are candidate rules, not universal guarantees. Without a correctness argument, label the method as a heuristic and validate its quality separately.</p>`)}
${section('frontier','Keep the reachable frontier',`<p>Let jump[i] be a nonnegative maximum forward jump. A reachable index can move by any integer length from zero through jump[i]. Under that contract, reachable positions form a prefix, so a single farthest index summarizes them.</p><pre tabindex="0" role="region" aria-label="Reachability Python"><code>def can_reach(jumps):
    farthest = 0
    for index, jump in enumerate(jumps):
        if index &gt; farthest:
            return False
        farthest = max(farthest, index + jump)
    return True</code></pre><p>The code assumes a sequence of nonnegative integer maximum jump lengths and does not validate that domain. Python integers keep the frontier exact. This convention treats empty input as having no unreachable position. An API that requires a destination can reject it instead. The first unreachable index cannot use its jump. Every later index lies beyond the same gap, so scanning its value would invent a route. Exact-length jumps, backward moves or forbidden landing cells need a different state; the prefix invariant no longer follows.</p><p>For the minimum number of jumps, scan reachable layers. Keep the current layer's end and the farthest next end contributed by its positions. Crossing a layer boundary increases the jump count. Reject a frontier that cannot advance when the destination remains beyond it; feasibility is not guaranteed by the count alone.</p>`)}
${traceLab('frontier-lab','A gap stops reachability','Maximum jumps [2,0,0,1]. Index 0 reaches 1 and 2, but neither reaches 3. The jump stored at 3 cannot repair the earlier gap.',frontierFrames,frontierFrames.length-1,frontierBody)}
${section('reset','Discard a harmful prefix',`${eq("\\begin{aligned}E_0&=G_0=a_0\\\\E_i&=\\max(a_i,E_{i-1}+a_i)\\\\G_i&=\\max(G_{i-1},E_i),\\qquad1\\le i<n\\end{aligned}","Nonempty length-n input, n ≥ 1, and a nonempty contiguous answer. Ei is the best sum ending exactly at i; Gi is the best sum anywhere through i. Explicit bases preserve all-negative inputs. Arithmetic must be exact or use a declared overflow policy.")}<p>A negative preceding sum can only lower a future extension compared with starting that extension fresh. Keep the best subarray ending at the current position and the best result seen globally.</p><pre tabindex="0" role="region" aria-label="Maximum subarray Python"><code>def maximum_subarray(values):
    if not values:
        raise ValueError("a nonempty subarray needs nonempty input")
    current = best = values[0]
    for value in values[1:]:
        current = max(value, current + value)
        best = max(best, current)
    return best</code></pre><p>Initializing best to zero instead would permit the empty selection and give the wrong answer when every value is negative. This algorithm is also a compressed DP recurrence; the labels greedy and DP do not override its state contract.</p><p>For a circular fuel route, let net[i]=fuel[i]−cost[i]. Nonnegative total net is necessary under an unlimited-tank contract. Maintain a candidate start and running tank. If the tank first becomes negative at i, restart at i+1.</p><p>Why discard every start between the old candidate and i? Earlier candidate-prefix sums were nonnegative before the first failure. Starting later subtracts one such prefix from the failing total, so it also cannot reach i+1. With nonnegative total, this elimination process leaves a feasible circular start. Capacity limits or changing costs require another argument.</p>`)}
${section('counts','Construction follows forced choices',`<p>Sometimes ordering makes a choice forced rather than merely attractive. To partition values into equal-length consecutive groups, the smallest remaining value must begin a group: no smaller unused value can precede it. Consume one of each required successor; a missing count proves impossibility.</p><p>A total count divisible by group length is necessary, but not sufficient. The ordered map or sorted-key scan costs must be included. Consuming the most frequent value first has no equivalent forced-choice proof.</p><p>For a string split so each symbol appears in at most one segment, record each symbol's last position. Extend the current segment end to the greatest last position encountered. Close it only when the scan reaches that end; closing earlier would put a symbol in two segments.</p><p>Other constructions retain several feasible quantities instead of one answer. For parentheses with a wildcard allowed to be open, closed or empty, keep the minimum and maximum reachable open counts. Reject a negative maximum; clamp the minimum to zero. Ending with minimum zero establishes some balanced assignment, not every assignment.</p><p>For componentwise target construction by merging compatible triples, discard any triple that exceeds a target component. A merge defined by componentwise maximum can never repair that excess. Among remaining triples, track which target components can be reached. These rules depend on the exact merge operation.</p>`)}
${section('endpoints','Endpoints are part of the problem',`${eq("\\begin{aligned}[a,b]\\cap[c,d]\\ne\\varnothing&\\ \\Longleftrightarrow\\ \\max(a,c)\\le\\min(b,d)\\\\{}[a,b)\\cap[c,d)\\ne\\varnothing&\\ \\Longleftrightarrow\\ \\max(a,c)<\\min(b,d)\\end{aligned}","Closed intervals require a ≤ b and c ≤ d and can contain a single point. The second equivalence assumes a &lt; b and c &lt; d; empty half-open intervals need separate handling. Endpoint equality changes overlap and must match sweep/release comparisons.")}<p>Half-open meeting [1,3) releases its room at 3, so [3,5) can use that room. Closed ranges [1,3] and [3,5] share point 3. The tie comparison must agree in merge, compatibility, heap removal and sweep events.</p><p>The labs use positive-duration intervals. Empty half-open intervals occupy no time and should be handled or filtered explicitly. Closed point intervals can overlap at a point. A merging API may intentionally coalesce adjacent half-open pieces to represent their union; that is a separate policy from merging only strictly overlapping pieces.</p>`)}
${section('merge','Sort starts to merge coverage',`<p>Sort by start. The result represents every processed interval and is ordered with no overlapping output pieces. Only its final piece can overlap the next input: any earlier piece ends before that final piece starts.</p><pre tabindex="0" role="region" aria-label="Closed interval merge Python"><code>def merge_intervals(intervals):
    # Finite comparable endpoints with start &lt;= end.
    merged = []
    for start, end in sorted(intervals):
        if not merged or start &gt; merged[-1][1]:
            merged.append([start, end])
        else:
            merged[-1][1] = max(merged[-1][1], end)
    return merged</code></pre><p>The function returns fresh endpoint lists and sorts a copy. Closed point intervals are valid; touching ranges merge. Invalid/reversed or nonfinite endpoints are outside this contract.</p><p>Update the expanding end. A nested interval need not extend it; a later interval may overlap the extension made by a previous input even when it does not overlap the first original interval. Output new records instead of mutating caller-owned endpoint pairs unexpectedly.</p>`)}
${traceLab('merge-lab','Only the last merged segment can overlap','Closed intervals [1,3], [2,4], [4,6], [8,9]. Touching counts as overlap, so the first three form [1,6].',mergeFrames,mergeFrames.length-1,mergeBody)}
${section('insert','Insertion has three phases',`<p>When existing intervals are already sorted and disjoint, insert a new interval in linear time: copy every interval entirely before it; merge consecutive overlaps into its growing bounds; copy the rest after it.</p><p>Use the endpoint policy to decide “before” and “after.” Compare against the updated new interval as it expands. Without the ordered-disjoint precondition, this three-phase scan can miss overlaps; normalize first or choose a different algorithm.</p>`)}
${section('scheduling','Sort finishes to keep the most intervals',`<p>To maximize the number of compatible positive-duration jobs on one resource, sort by finish. Keep the next interval whose start is at least the previous finish under half-open compatibility.</p><p>Take an optimal schedule's first interval o and the earliest-finishing candidate g. Replacing o with g preserves the count. Every later interval starts after o ends, and g ends no later, so those later intervals remain compatible. Apply the same argument to the remaining compatible suffix. ${cite('https://www.cs.princeton.edu/~wayne/kleinberg-tardos/pdf/04GreedyAlgorithmsI.pdf','Earliest-finish exchange proof')}</p><p>The minimum deletions to eliminate overlaps is n minus the maximum kept count. Different tie orders can select different optimal schedules. This rule does not maximize total job value: a longer high-value interval can outweigh several short jobs. Weighted scheduling keeps a different DP state.</p>`)}
${scheduleLab}
${section('rooms','Room count is maximum simultaneous demand',`<p>Scheduling for maximum count discards jobs. Room allocation must keep all jobs. Sort by start and maintain active finish times in a min-heap. Remove every finish ≤ the current start for half-open meetings; push the new finish; track the maximum heap size, not just its final size.</p><p>The heap version here counts active meetings. A room-assignment heap can instead retain one latest finish per room and reuse an available room; those heap sizes mean allocated rooms, not active meetings. Do not mix their invariants.</p><p>At a time when d jobs overlap, any schedule needs at least d rooms. Greedy allocation opens a room only when every existing room still has an overlapping job. At that instant the new job witnesses the same lower bound. Thus unlimited identical rooms suffice in exactly the maximum-overlap count. ${cite('https://www.cs.princeton.edu/~wayne/kleinberg-tardos/pdf/04GreedyAlgorithmsI.pdf','Partitioning lower-bound proof')}</p><p>A sweep exposes the same demand without assigning room identifiers. Add +1 at starts and −1 at ends; sort coordinates and tie events according to endpoint inclusion. The maximum prefix count is the overlap depth.</p>`)}
${sweepLab}
${section('queries','Heap priorities depend on the query',`<p>An interval's earliest end is useful for releasing a room. It is not the answer to every interval query. For the shortest closed interval covering each point, sort queries and intervals by start. Add intervals that have begun to a heap keyed by length, with end as validity metadata.</p><p>Before answering, remove heap-top candidates whose end is before the query. An expired entry below the top can stay until it rises; the top must be valid when read. Preserve original query indices to restore caller order. The empty heap means no covering interval.</p><p>For integer closed coordinates, inclusive length is end−start+1. Geometric length uses end−start. Sorting plus heap operations typically costs O((n+q) log(n+q)); exact accounting depends on the implementation. A bounded coordinate domain can use difference/prefix arrays for overlap counts, but not automatically for minimum covering length.</p>`)}
${section('choose','Choose an objective before choosing an order',`${table('Interval ordering is objective-specific',['Goal','Order/state','Scope'],[['Merge coverage','Start order + expanding last end','Endpoint/adjacency policy'],['Insert one range','Three-phase scan','Already ordered and disjoint input'],['Maximum compatible count','Finish order + last selected end','Unweighted one-resource jobs'],['All jobs with fewest rooms','Start order + active finishes','Identical resources; endpoint release'],['Maximum overlap','Sorted signed events','Tie policy defines inclusion'],['Shortest covering range','Query order + length-priority candidates','Discard invalid top entries']])}<p>Most of these routines cost O(n log n) sorting plus scanning or heap work. A linear scan does not make the full unsorted algorithm O(n). If endpoints are bounded, include coordinate-domain size in an array-based alternative.</p><p>Test nested ranges, touching endpoints, equal starts/ends, empty input, a late long job, and a long early job blocking several short ones. Compare tiny scheduling instances against exhaustive subsets. Proofs supply guarantees; counterexamples diagnose a rule's limits.</p>`)}
${section('sources','Sources and related mechanisms',`<p>${cite('https://www.cs.princeton.edu/~wayne/kleinberg-tardos/pdf/04GreedyAlgorithmsI.pdf','Interval scheduling and partitioning proofs')} support the exchange and overlap arguments above. <a href="${link('algorithms/dp#state')}">Dynamic Programming →</a> retains alternatives when dominance fails. <a href="${link('algorithms/ordering#priority')}">Priority queues →</a> implement release and covering-query frontiers.</p><p>The timelines use exact fixed toy inputs. Bar positions depict numeric endpoints, not execution time or measured performance.</p>`)}
`);}
export function mountGreedy(scope=document){mountTopic(scope,greedyMeta.slug,article=>{
  mountTrace(article,'frontier-lab',frontierFrames,frontierBody);mountTrace(article,'merge-lab',mergeFrames,mergeBody);
  for(const [id,initial,body,make]of [['schedule-lab',schedules,scheduleBody,v=>schedulingTrace(schedulingJobs,v)],['sweep-lab',events,(f,v)=>sweepBody(f,v==='closed'),v=>overlapTrace(meetingJobs,v==='closed')]]){
    const lab=article.querySelector('#'+id),select=lab.querySelector('select');let fs=initial;
    const playback=rangePlayback(article,lab,i=>{lab.querySelector('[data-step]').textContent=i;lab.querySelector('[data-trace-body]').innerHTML=body(fs[i],select.value);},14000);
    select.addEventListener('change',()=>{playback.stop();fs=make(select.value);playback.render();});
  }
});}
